PRAGMA defer_foreign_keys=TRUE;
CREATE TABLE report_runs (id INTEGER PRIMARY KEY AUTOINCREMENT, report_date_et TEXT NOT NULL, market_overview TEXT, market_overview_en TEXT, created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP));
CREATE TABLE report_quotes (id INTEGER PRIMARY KEY AUTOINCREMENT, run_id INTEGER NOT NULL, symbol TEXT NOT NULL, name TEXT NOT NULL, close REAL NOT NULL, previous_close REAL NOT NULL, change_pct REAL NOT NULL, volume INTEGER NOT NULL, turnover_estimate REAL NOT NULL, currency TEXT NOT NULL, FOREIGN KEY(run_id) REFERENCES report_runs(id));
CREATE TABLE report_news (id INTEGER PRIMARY KEY AUTOINCREMENT, run_id INTEGER NOT NULL, symbol TEXT NOT NULL, title TEXT NOT NULL, link TEXT NOT NULL, source TEXT NOT NULL, published_at TEXT NOT NULL, ai_summary TEXT, ai_summary_en TEXT, FOREIGN KEY(run_id) REFERENCES report_runs(id));
CREATE TABLE stocks (id INTEGER PRIMARY KEY AUTOINCREMENT, symbol TEXT NOT NULL, name TEXT NOT NULL, display_name TEXT NOT NULL, codes TEXT NOT NULL, business_type TEXT NOT NULL, aliases_json TEXT NOT NULL DEFAULT '[]', is_active INTEGER NOT NULL DEFAULT 1, sort_order INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), updated_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP), deleted_at TEXT);
DELETE FROM sqlite_sequence;
CREATE UNIQUE INDEX idx_report_runs_date_unique ON report_runs(report_date_et);
CREATE INDEX idx_report_runs_date ON report_runs(report_date_et);
CREATE INDEX idx_report_quotes_symbol_run ON report_quotes(symbol, run_id);
CREATE INDEX idx_report_news_run_symbol ON report_news(run_id, symbol);
CREATE INDEX idx_report_news_symbol_run ON report_news(symbol, run_id);
CREATE UNIQUE INDEX idx_stocks_symbol_unique ON stocks(symbol);
CREATE INDEX idx_stocks_active_sort ON stocks(is_active, sort_order, id);